package com.ultimatebank;

import com.google.inject.Provides;
import com.ultimatebank.core.BankFeature;
import com.ultimatebank.core.FeatureManager;
import com.ultimatebank.core.FeatureRollout;
import com.ultimatebank.core.snapshots.StorageSnapshots;
import com.ultimatebank.feature.storagesavings.StorageSavingsFeature;
import com.ultimatebank.feature.banksearch.BankSearchFeature;
import com.ultimatebank.feature.banktweaks.BankTweaksFeature;
import java.util.List;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.banktags.BankTagsPlugin;

@Slf4j
// Needed to inject core bank tag services (BankTagsService, TagManager)
@PluginDependency(BankTagsPlugin.class)
@PluginDescriptor(
	name = "Ultimate Bank",
	description = "Free up bank space and find anything you own: storable item markers, POH upgrade hints, and a bank and POH search",
	tags = {"bank", "storage", "poh", "costume", "space", "stash", "tackle box", "seed vault", "wasted", "search", "find", "history"}
)
public class UltimateBankPlugin extends Plugin
{
	/**
	 * Every feature in the plugin. Add new features here (order = start order).
	 */
	private static final List<Class<? extends BankFeature>> FEATURES = List.of(
		StorageSavingsFeature.class,
		BankSearchFeature.class,
		BankTweaksFeature.class
	);

	/**
	 * Enable keys of features added after v1.0.0: on for new installs, off for people updating (see
	 * {@link FeatureRollout}). Add every new feature's toggle here; never remove one.
	 */
	private static final List<String> NEW_FEATURE_TOGGLES = List.of(
		"bankSearchEnabled",
		"bankTweaksEnabled"
	);

	@Inject
	private ClientThread clientThread;

	@Inject
	private FeatureManager featureManager;

	@Inject
	private FeatureRollout featureRollout;

	@Inject
	private EventBus eventBus;

	@Inject
	private StorageSnapshots storageSnapshots;

	@Override
	protected void startUp()
	{
		// Shared services run whatever features are on
		eventBus.register(storageSnapshots);
		clientThread.invokeLater(storageSnapshots::load);

		featureRollout.apply(NEW_FEATURE_TOGGLES);
		featureManager.load(FEATURES);
		log.debug("Loaded {} features", FEATURES.size());
		clientThread.invokeLater(featureManager::sync);
	}

	@Override
	protected void shutDown()
	{
		clientThread.invokeLater(featureManager::stopAll);
		eventBus.unregister(storageSnapshots);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (UltimateBankConfig.GROUP.equals(event.getGroup()))
		{
			clientThread.invokeLater(featureManager::sync);
		}
	}

	@Provides
	UltimateBankConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(UltimateBankConfig.class);
	}
}

package com.ultimatebank.core;

import com.ultimatebank.UltimateBankConfig;

/**
 * A self-contained feature of the plugin (e.g. bank value, tag layouts).
 * <p>
 * While enabled, the feature instance is registered on the EventBus, so it may declare
 * {@code @Subscribe} methods directly. Features are Guice singletons created by the plugin's
 * injector, so they may {@code @Inject} anything the plugin can.
 * <p>
 * To add a feature, follow .claude/skills/new-feature/SKILL.md.
 */
public interface BankFeature
{
	/**
	 * Whether the user has this feature switched on. Usually reads a single toggle from config.
	 */
	boolean isEnabled(UltimateBankConfig config);

	/**
	 * Called on the client thread after the feature is registered on the EventBus.
	 * Add overlays, build caches, etc. here.
	 */
	default void startUp()
	{
	}

	/**
	 * Called on the client thread before the feature is unregistered from the EventBus.
	 * Must undo everything startUp() did (remove overlays, restore widgets, clear caches).
	 */
	default void shutDown()
	{
	}
}

package com.ultimatebank.core;

import com.google.inject.Injector;
import com.ultimatebank.UltimateBankConfig;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.eventbus.EventBus;

/**
 * Starts and stops {@link BankFeature}s so that exactly the enabled ones are running.
 * All methods must be called on the client thread.
 */
@Slf4j
@Singleton
public class FeatureManager
{
	private final Injector injector;
	private final EventBus eventBus;
	private final UltimateBankConfig config;

	private final List<BankFeature> features = new ArrayList<>();
	private final Set<BankFeature> running = new LinkedHashSet<>();

	@Inject
	FeatureManager(Injector injector, EventBus eventBus, UltimateBankConfig config)
	{
		this.injector = injector;
		this.eventBus = eventBus;
		this.config = config;
	}

	public void load(List<Class<? extends BankFeature>> featureClasses)
	{
		features.clear();
		for (Class<? extends BankFeature> featureClass : featureClasses)
		{
			features.add(injector.getInstance(featureClass));
		}
	}

	/**
	 * Starts newly enabled features and stops newly disabled ones.
	 */
	public void sync()
	{
		log.debug("Syncing {} features ({} running)", features.size(), running.size());
		for (BankFeature feature : features)
		{
			boolean enabled = feature.isEnabled(config);
			if (enabled && !running.contains(feature))
			{
				start(feature);
			}
			else if (!enabled && running.contains(feature))
			{
				stop(feature);
			}
		}
	}

	public void stopAll()
	{
		for (BankFeature feature : new ArrayList<>(running))
		{
			stop(feature);
		}
	}

	private void start(BankFeature feature)
	{
		log.debug("Starting feature {}", feature.getClass().getSimpleName());
		eventBus.register(feature);
		running.add(feature);
		try
		{
			feature.startUp();
		}
		catch (Exception e)
		{
			log.warn("Feature {} failed to start", feature.getClass().getSimpleName(), e);
			stop(feature);
		}
	}

	private void stop(BankFeature feature)
	{
		log.debug("Stopping feature {}", feature.getClass().getSimpleName());
		try
		{
			feature.shutDown();
		}
		catch (Exception e)
		{
			log.warn("Feature {} failed to shut down cleanly", feature.getClass().getSimpleName(), e);
		}
		eventBus.unregister(feature);
		running.remove(feature);
	}
}

package com.ultimatebank.core;

import com.ultimatebank.UltimateBankConfig;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.RuneScapeProfile;

/**
 * New features ship on for new installs and off for people updating. A config item has one default for everyone, so
 * their toggles default to on and, the first time an update sees one, it's switched off if the plugin was already in
 * use. Remembers which toggles it has handled, so each is decided once.
 */
@Slf4j
@Singleton
public class FeatureRollout
{
	/** Comma-separated toggle keys already handled */
	private static final String SEEN_KEY = "featuresSeen";
	/** Saved by Storage savings when it first adds its tag tab (every v1.x install, unless that option was off) */
	private static final String TAG_TAB_CREATED_KEY = "storageSavingsTagTabCreated";

	private final ConfigManager configManager;

	@Inject
	FeatureRollout(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	/**
	 * Call before features are started.
	 *
	 * @param toggles enable keys of features that should be off for existing installs
	 */
	public void apply(List<String> toggles)
	{
		String seen = configManager.getConfiguration(UltimateBankConfig.GROUP, SEEN_KEY);
		// Only data the plugin writes itself shows it was already in use: RuneLite saves every setting's default when
		// the plugin loads, so saved settings prove nothing. Storage savings records its tag tab on first start, and
		// per-account data (bank snapshots, detected tiers) lives in the RS profile store
		boolean tagTabCreated = configManager.getConfiguration(UltimateBankConfig.GROUP, TAG_TAB_CREATED_KEY) != null;
		boolean accountData = hasAccountData();
		boolean anyKeys = tagTabCreated || accountData;
		log.debug("Feature rollout: seen={}, tag tab created={}, account data={} ({} accounts known)", seen,
			tagTabCreated, accountData, configManager.getRSProfiles().size());
		// RuneLite saves a new setting's default (on) when the plugin loads, before this runs, so a saved "true" isn't
		// a choice. Only the user can have turned a toggle off
		Set<String> userSet = new HashSet<>();
		for (String toggle : toggles)
		{
			if ("false".equals(configManager.getConfiguration(UltimateBankConfig.GROUP, toggle)))
			{
				userSet.add(toggle);
			}
		}

		for (String toggle : toDisable(seen, anyKeys, toggles, userSet))
		{
			log.debug("Existing install: {} starts off", toggle);
			configManager.setConfiguration(UltimateBankConfig.GROUP, toggle, false);
		}

		Set<String> nowSeen = parse(seen);
		if (nowSeen.addAll(toggles) || seen == null)
		{
			configManager.setConfiguration(UltimateBankConfig.GROUP, SEEN_KEY, String.join(",", nowSeen));
		}
	}

	private boolean hasAccountData()
	{
		for (RuneScapeProfile profile : configManager.getRSProfiles())
		{
			if (!configManager.getRSProfileConfigurationKeys(UltimateBankConfig.GROUP, profile.getKey(), "").isEmpty())
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * @param seen    the saved list of handled toggles, or null if none has been saved yet
	 * @param anyKeys whether the plugin has saved data of its own (it was in use before)
	 * @param userSet toggles the user already turned off
	 * @return the toggles to switch off
	 */
	static List<String> toDisable(String seen, boolean anyKeys, List<String> toggles, Set<String> userSet)
	{
		boolean existingInstall = seen != null || anyKeys;
		Set<String> handled = parse(seen);
		List<String> off = new ArrayList<>();
		if (!existingInstall)
		{
			return off;
		}
		for (String toggle : toggles)
		{
			if (!handled.contains(toggle) && !userSet.contains(toggle))
			{
				off.add(toggle);
			}
		}
		return off;
	}

	private static Set<String> parse(String seen)
	{
		Set<String> keys = new LinkedHashSet<>();
		if (seen != null && !seen.isEmpty())
		{
			keys.addAll(Arrays.asList(seen.split(",")));
		}
		return keys;
	}
}

package com.ultimatebank.core;

import com.ultimatebank.UltimateBankPlugin;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.MenuAction;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.OverlayMenuClicked;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayMenuEntry;

/**
 * Opens the plugin's settings in the RuneLite configuration panel, e.g. from a feature's sidebar panel.
 * There's no direct API for this; the core Configuration plugin opens a plugin's settings when one of its overlays'
 * "Configure" menu entries is clicked, so we post that event for an overlay belonging to our plugin.
 */
@Singleton
public class SettingsOpener
{
	private static final OverlayMenuEntry CONFIGURE = new OverlayMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG, "Configure", "Ultimate Bank");

	private final ClientThread clientThread;
	private final EventBus eventBus;
	private final Overlay owner;

	@Inject
	SettingsOpener(ClientThread clientThread, EventBus eventBus, UltimateBankPlugin plugin)
	{
		this.clientThread = clientThread;
		this.eventBus = eventBus;
		// Never added to the overlay manager; it only tells the Configuration plugin whose settings to open
		this.owner = new Overlay(plugin)
		{
			@Override
			public Dimension render(Graphics2D graphics)
			{
				return null;
			}
		};
	}

	/**
	 * Opens Ultimate Bank's settings. Safe to call from any thread.
	 */
	public void open()
	{
		// Overlay menu clicks are normally posted on the client thread
		clientThread.invokeLater(() -> eventBus.post(new OverlayMenuClicked(CONFIGURE, owner)));
	}
}

package com.ultimatebank.core.snapshots;

import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;

/**
 * Storages the game sends as an item container while their interface is open, so they're read like the bank.
 */
enum ContainerStorage
{
	PET_HOUSE(SnapshotLocation.PET_HOUSE, InventoryID.POH_MENAGERIE_PETS, InterfaceID.POH_MENAGERIE),
	SEED_VAULT(SnapshotLocation.SEED_VAULT, InventoryID.SEED_VAULT, InterfaceID.SEED_VAULT),
	TACKLE_BOX(SnapshotLocation.TACKLE_BOX, InventoryID.TACKLE_BOX, InterfaceID.TACKLE_BOX_MAIN),
	HUNTSMANS_KIT(SnapshotLocation.HUNTSMANS_KIT, InventoryID.HUNTSMANS_KIT, InterfaceID.HUNTSMANS_KIT),
	FORESTRY_KIT(SnapshotLocation.FORESTRY_KIT, InventoryID.FORESTRY_KIT, InterfaceID.FORESTRY_KIT_MAIN);

	final SnapshotLocation location;
	final int inventoryId;
	/** Interface group shown while it's open */
	final int interfaceId;

	ContainerStorage(SnapshotLocation location, int inventoryId, int interfaceId)
	{
		this.location = location;
		this.inventoryId = inventoryId;
		this.interfaceId = interfaceId;
	}

	/**
	 * @return the storage with this item container, or null
	 */
	static ContainerStorage forInventory(int inventoryId)
	{
		for (ContainerStorage storage : values())
		{
			if (storage.inventoryId == inventoryId)
			{
				return storage;
			}
		}
		return null;
	}

	/**
	 * @return the storage recorded as this location, or null
	 */
	static ContainerStorage forLocation(SnapshotLocation location)
	{
		for (ContainerStorage storage : values())
		{
			if (storage.location == location)
			{
				return storage;
			}
		}
		return null;
	}

	/**
	 * @return the storage shown by this interface group, or null
	 */
	static ContainerStorage forInterface(int interfaceId)
	{
		for (ContainerStorage storage : values())
		{
			if (storage.interfaceId == interfaceId)
			{
				return storage;
			}
		}
		return null;
	}
}

package com.ultimatebank.core.snapshots;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * The keys seen on the steel key ring while its interface is open. The game shows one key at a time (with the
 * previous and next ones as buttons) plus a total, so the ring is known once every key has been paged past, or once
 * the keys last recorded plus those just seen add up to the total. Removing a key shows the next one with a total one
 * lower, so the key that was showing is the one removed. Pure.
 */
final class KeyRingKeys
{
	private final Set<Integer> seen = new HashSet<>();
	/** Keys taken off the ring this login, until one is added again */
	private final Set<Integer> removed = new HashSet<>();
	private int total = -1;
	/** The key the ring is showing, or -1 */
	private int shown = -1;

	void see(int itemId)
	{
		if (itemId > 0)
		{
			seen.add(itemId);
		}
	}

	/**
	 * The ring now shows this key (call after {@link #setTotal}).
	 */
	void show(int itemId)
	{
		see(itemId);
		shown = itemId;
	}

	/**
	 * A new total means a key was added or removed: the keys seen so far may include one that's gone, so start over.
	 * One fewer, while a key was showing, means that key was removed. Keys seen before the first total are kept.
	 */
	void setTotal(int total)
	{
		if (total == this.total)
		{
			return;
		}
		if (this.total >= 0)
		{
			seen.clear();
			if (total == this.total - 1 && shown > 0)
			{
				removed.add(shown);
			}
			else if (total > this.total)
			{
				removed.clear();
			}
		}
		this.total = total;
		shown = -1;
	}

	int getTotal()
	{
		return total;
	}

	int seenCount()
	{
		return seen.size();
	}

	/**
	 * @param previous the keys last recorded, or empty
	 * @return the ring's keys (one of each), or null if they aren't known yet
	 */
	Map<Integer, Integer> contents(Set<Integer> previous)
	{
		if (total < 0)
		{
			return null;
		}
		Set<Integer> keys = new HashSet<>(seen);
		if (keys.size() < total)
		{
			keys.addAll(previous);
			keys.removeAll(removed);
			keys.addAll(seen);
		}
		if (keys.size() != total)
		{
			return null;
		}
		Map<Integer, Integer> contents = new HashMap<>();
		keys.forEach(key -> contents.put(key, 1));
		return contents;
	}

	/**
	 * @return the key named by "You add the dusty key to your key ring." (lower case), or null
	 */
	static String addedKey(String message)
	{
		return keyIn(message, "you add the ", " to your key ring.");
	}

	/**
	 * @return the key named by "You remove the dusty key from your key ring." (lower case), or null
	 */
	static String removedKey(String message)
	{
		return keyIn(message, "you remove the ", " from your key ring.");
	}

	private static String keyIn(String message, String start, String end)
	{
		if (message == null)
		{
			return null;
		}
		String text = message.replaceAll("<[^>]*>", "").trim().toLowerCase(Locale.ROOT);
		if (!text.startsWith(start) || !text.endsWith(end) || text.length() <= start.length() + end.length())
		{
			return null;
		}
		return text.substring(start.length(), text.length() - end.length());
	}

	/**
	 * @return the number in the interface's "Key total: N" text, or -1
	 */
	static int parseTotal(String text)
	{
		if (text == null)
		{
			return -1;
		}
		String digits = text.replaceAll("<[^>]*>", "").replaceAll("[^0-9]", "");
		if (digits.isEmpty() || digits.length() > 3)
		{
			return -1;
		}
		return Integer.parseInt(digits);
	}
}

package com.ultimatebank.core.snapshots;

import java.util.HashSet;
import java.util.Set;
import java.util.function.IntUnaryOperator;

/**
 * Pets living in the house menagerie, decoded as the game's [proc,poh_menagerie_drawlist] does: one bit per pet over
 * three varps, the pet's item from game enum 985. Pet items kept there are in its item container instead. Pure.
 */
final class MenageriePets
{
	/** Game enum mapping a pet's bit to its item (enum_985 in the game's scripts) */
	static final int PETS_ENUM = 985;
	/** Bits 0-31 are in the first varp, 32-62 in the second and 63-93 in the third */
	private static final int SECOND_VARP_START = 32;
	private static final int THIRD_VARP_START = 63;
	private static final int END = 94;

	private MenageriePets()
	{
	}

	/**
	 * @param varps   the three varps, in order
	 * @param petItem a pet bit's item, or a value below 1 if there's none
	 * @return the item of each pet living there
	 */
	static Set<Integer> read(int[] varps, IntUnaryOperator petItem)
	{
		Set<Integer> pets = new HashSet<>();
		for (int bit = 0; bit < END; bit++)
		{
			int varp;
			int shift;
			if (bit < SECOND_VARP_START)
			{
				varp = varps[0];
				shift = bit;
			}
			else if (bit < THIRD_VARP_START)
			{
				varp = varps[1];
				shift = bit - SECOND_VARP_START;
			}
			else
			{
				varp = varps[2];
				shift = bit - THIRD_VARP_START;
			}
			if ((varp >>> shift & 1) == 1)
			{
				int item = petItem.applyAsInt(bit);
				if (item > 0)
				{
					pets.add(item);
				}
			}
		}
		return pets;
	}
}

