package com.ultimatebank.core.snapshots;

import java.util.HashMap;
import java.util.Map;
import java.util.function.IntUnaryOperator;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.ScriptID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;

/**
 * Reads the bank's potion store: doses of each potion, worked out by the game's own script, plus empty vials.
 * Ported from RuneLite's bank tags PotionStorage (Adam, BSD-2), which isn't usable from a plugin.
 * Must run on the client thread, outside any script callback (it runs scripts itself).
 */
@Singleton
class PotionStorageReader
{
	private static final int MAX_DOSES = 4;

	private final Client client;

	@Inject
	PotionStorageReader(Client client)
	{
		this.client = client;
	}

	/**
	 * @return item ID to quantity, each potion as its fewest-dose form so no dose is lost, or null if the game's
	 * potion lists aren't loaded
	 */
	Map<Integer, Integer> read()
	{
		EnumComposition potions = client.getEnum(EnumID.POTIONSTORE_POTIONS);
		EnumComposition unfinished = client.getEnum(EnumID.POTIONSTORE_UNFINISHED_POTIONS);
		if (potions == null || unfinished == null)
		{
			return null;
		}

		Map<Integer, Integer> items = new HashMap<>();
		for (EnumComposition list : new EnumComposition[]{potions, unfinished})
		{
			for (int potionEnumId : list.getIntVals())
			{
				EnumComposition potion = client.getEnum(potionEnumId);
				if (potion == null)
				{
					continue;
				}
				client.runScript(ScriptID.POTIONSTORE_DOSES, potionEnumId);
				int doses = client.getIntStack()[0];
				addDoses(items, potion::getIntValue, doses);
			}
		}

		int vials = client.getVarpValue(VarPlayerID.POTIONSTORE_VIALS);
		if (vials > 0)
		{
			items.merge(ItemID.VIAL_EMPTY, vials, Integer::sum);
		}
		return items;
	}

	/**
	 * Adds a potion's doses as its fewest-dose item (unfinished potions only have one form).
	 *
	 * @param doseItem the potion's item for a dose count, or a value below 1 if it has none
	 */
	static void addDoses(Map<Integer, Integer> items, IntUnaryOperator doseItem, int doses)
	{
		if (doses <= 0)
		{
			return;
		}
		for (int dose = 1; dose <= MAX_DOSES; dose++)
		{
			int itemId = doseItem.applyAsInt(dose);
			if (itemId > 0)
			{
				int quantity = doses / dose;
				if (quantity > 0)
				{
					items.merge(itemId, quantity, Integer::sum);
				}
				return;
			}
		}
	}
}

package com.ultimatebank.core.snapshots;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import lombok.EqualsAndHashCode;
import lombok.Getter;

/**
 * Item quantities in one location at one moment. Stored as JSON, so fields stay simple.
 */
@Getter
@EqualsAndHashCode
public final class Snapshot
{
	/** Quantity by item ID, as the game reports them (placeholders excluded) */
	private final Map<Integer, Integer> quantities;
	/** When it was taken, epoch millis */
	private final long takenAt;

	public Snapshot(Map<Integer, Integer> quantities, long takenAt)
	{
		this.quantities = Collections.unmodifiableMap(new HashMap<>(quantities));
		this.takenAt = takenAt;
	}

	/**
	 * @return e.g. "5 minutes ago", "3 hours ago", "2 days ago"
	 */
	public static String ago(long epochMillis)
	{
		long minutes = Math.max(0, (System.currentTimeMillis() - epochMillis) / 60_000);
		if (minutes < 60)
		{
			return minutes + (minutes == 1 ? " minute ago" : " minutes ago");
		}
		long hours = minutes / 60;
		if (hours < 48)
		{
			return hours + (hours == 1 ? " hour ago" : " hours ago");
		}
		return hours / 24 + " days ago";
	}

	public boolean sameContents(Snapshot other)
	{
		return other != null && quantities.equals(other.quantities);
	}
}

package com.ultimatebank.core.snapshots;

import java.util.List;

/**
 * Updates a location's snapshot history (oldest first) so it holds one entry per visit.
 */
final class SnapshotHistory
{
	private SnapshotHistory()
	{
	}

	/**
	 * Records a snapshot taken during a visit.
	 *
	 * @param replaceLast the last entry was appended earlier in this same visit, so this snapshot replaces it
	 * @return whether the history's last entry now belongs to this visit (pass it as replaceLast next time)
	 */
	static boolean record(List<Snapshot> history, Snapshot snapshot, boolean replaceLast, int max)
	{
		if (replaceLast && !history.isEmpty())
		{
			history.remove(history.size() - 1);
		}

		boolean appended;
		if (!history.isEmpty() && history.get(history.size() - 1).sameContents(snapshot))
		{
			// Unchanged since the last visit: just note it was seen now
			history.set(history.size() - 1, snapshot);
			appended = false;
		}
		else
		{
			history.add(snapshot);
			appended = true;
		}
		while (history.size() > max)
		{
			history.remove(0);
		}
		return appended;
	}
}

package com.ultimatebank.core.snapshots;

import java.util.Locale;
import lombok.Getter;

/**
 * Places whose contents are snapshotted: the bank, each player-owned house costume room storage, and the storages
 * read from an item container ({@link ContainerStorage}) or varbits ({@link VarbitStorage}). New values go at the end: the order is the panel's order.
 */
@Getter
public enum SnapshotLocation
{
	BANK("Bank", false),
	MAGIC_WARDROBE("POH magic wardrobe", true),
	TOY_BOX("POH toy box", true),
	CAPE_RACK("POH cape rack", true),
	TREASURE_CHEST("POH treasure chest", true),
	ARMOUR_CASE("POH armour case", true),
	FANCY_DRESS_BOX("POH fancy dress box", true),
	BOOKCASE("POH bookcase", true),
	// Read from an item container while open (ContainerStorage)
	PET_HOUSE("POH pet house", true),
	SEED_VAULT("Seed vault", false),
	TACKLE_BOX("Tackle box", false),
	HUNTSMANS_KIT("Huntsman's kit", false),
	FORESTRY_KIT("Forestry kit", false),
	// Read from varbits (VarbitStorage)
	TOOL_LEPRECHAUN("Tool leprechaun", false),
	FOSSIL_STORAGE("Fossil storage", false),
	MASTER_SCROLL_BOOK("Master scroll book", false),
	NIGHTMARE_ZONE("Nightmare Zone", false),
	ELNOCK_INQUISITOR("Elnock Inquisitor", false),
	MYSTERIOUS_STRANGER("Mysterious stranger", false),
	// Read from its interface while you page through it (KeyRingReader)
	STEEL_KEY_RING("Steel key ring", false),
	// Read from the bank's potion store (PotionStorageReader)
	POTION_STORAGE("Potion storage", false);

	private final String displayName;
	private final boolean poh;

	SnapshotLocation(String displayName, boolean poh)
	{
		this.displayName = displayName;
		this.poh = poh;
	}

	/**
	 * Works out which POH storage an interface is showing from its text, e.g. a "Toy box" title.
	 * From Where's My Stuff by Wozak-1.
	 *
	 * @return the storage, or null if the text names none
	 */
	public static SnapshotLocation fromInterfaceText(String text)
	{
		if (text == null)
		{
			return null;
		}
		String t = text.toLowerCase(Locale.ROOT);
		if (t.contains("magic wardrobe"))
		{
			return MAGIC_WARDROBE;
		}
		if (t.contains("toy box"))
		{
			return TOY_BOX;
		}
		if (t.contains("cape rack"))
		{
			return CAPE_RACK;
		}
		if (t.contains("treasure chest"))
		{
			return TREASURE_CHEST;
		}
		if (t.contains("armour case") || t.contains("armor case"))
		{
			return ARMOUR_CASE;
		}
		if (t.contains("fancy dress box") || t.contains("costume box"))
		{
			return FANCY_DRESS_BOX;
		}
		if (t.contains("bookcase") || t.contains("bookshelf"))
		{
			return BOOKCASE;
		}
		return null;
	}
}

package com.ultimatebank.core.snapshots;

