package com.ultimatebank.feature.banksearch;

import net.runelite.api.gameval.ItemID;

/**
 * Which price the Ultimate Bank Search panel values items at.
 */
public enum ValueType
{
	/** Grand Exchange price; high alch value for untradeables */
	GE("GE price"),
	HIGH_ALCH("High alch");

	private final String label;

	ValueType(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}

	/**
	 * @param gePrice the item's GE price (0 if untradeable)
	 * @param haPrice the item's high alch value
	 * @return one item's value
	 */
	long unitPrice(int itemId, long gePrice, long haPrice)
	{
		// Coins and platinum tokens alch for nothing, but are money
		if (itemId == ItemID.COINS)
		{
			return 1;
		}
		if (itemId == ItemID.PLATINUM)
		{
			return 1_000;
		}
		if (this == HIGH_ALCH)
		{
			return haPrice;
		}
		return gePrice > 0 ? gePrice : haPrice;
	}
}

package com.ultimatebank.feature.banksearch;

import com.ultimatebank.core.snapshots.Snapshot;
import com.ultimatebank.core.snapshots.SnapshotLocation;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import lombok.Value;

/**
 * What each visit to a location changed, from its snapshots (one per visit). Pure: no client access.
 */
final class VisitLog
{
	private VisitLog()
	{
	}

	@Value
	static class Visit
	{
		SnapshotLocation location;
		long takenAt;
		/** Quantity change by item ID (negative = taken out) */
		Map<Integer, Integer> changes;
	}

	/**
	 * @param histories each location's snapshots, oldest first
	 * @return visits that changed something, newest first. A location's first snapshot has nothing to compare with,
	 * so it isn't a visit.
	 */
	static List<Visit> build(Map<SnapshotLocation, List<Snapshot>> histories)
	{
		List<Visit> visits = new ArrayList<>();
		histories.forEach((location, history) ->
		{
			for (int i = 1; i < history.size(); i++)
			{
				Snapshot visit = history.get(i);
				Map<Integer, Integer> changes = SnapshotDiff.changes(history.get(i - 1).getQuantities(), visit.getQuantities());
				if (!changes.isEmpty())
				{
					visits.add(new Visit(location, visit.getTakenAt(), changes));
				}
			}
		});
		visits.sort(Comparator.comparingLong(Visit::getTakenAt).reversed());
		return visits;
	}
}

package com.ultimatebank.feature.banktweaks;

import com.ultimatebank.UltimateBankConfig;
import com.ultimatebank.core.BankFeature;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.Menu;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.PostMenuSort;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Small changes to how the bank handles clicks. Each only reorders a menu's existing options (like core's Menu Entry
 * Swapper), so nothing new is sent to the server.
 */
@Singleton
public class BankTweaksFeature implements BankFeature
{
	/** Core Bank Tags' "+" button below the tag tabs (TabInterface) */
	static final String NEW_TAG_TAB = "New tag tab";
	static final String VIEW_TAG_TABS = "View tag tabs";

	@Inject
	private Client client;

	@Inject
	private UltimateBankConfig config;

	@Override
	public boolean isEnabled(UltimateBankConfig config)
	{
		return config.bankTweaksEnabled();
	}

	@Subscribe
	public void onPostMenuSort(PostMenuSort event)
	{
		if (client.isMenuOpen() || !config.bankTweaksViewTagTabs())
		{
			return;
		}

		Menu menu = client.getMenu();
		MenuEntry[] entries = menu.getMenuEntries();
		int top = entries.length - 1;
		// Cheap check first: this runs every frame
		if (top < 1 || !NEW_TAG_TAB.equals(Text.removeTags(entries[top].getOption())))
		{
			return;
		}

		List<Option> options = new ArrayList<>(entries.length);
		for (MenuEntry entry : entries)
		{
			options.add(new Option(Text.removeTags(entry.getOption()), entry.getParam0(), entry.getParam1()));
		}
		int swap = leftClickSwap(options);
		if (swap != -1)
		{
			MenuEntry leftClick = entries[top];
			entries[top] = entries[swap];
			entries[swap] = leftClick;
			menu.setMenuEntries(entries);
		}
	}

	/** A menu entry's option text (tags removed) and the widget it's on */
	@Value
	static class Option
	{
		String text;
		int param0;
		int param1;
	}

	/**
	 * @param options menu entries in client order (the last one is the left-click)
	 * @return the index of the "View tag tabs" entry to swap with a left-click "New tag tab", or -1
	 */
	static int leftClickSwap(List<Option> options)
	{
		int top = options.size() - 1;
		if (top < 1 || !NEW_TAG_TAB.equals(options.get(top).getText()))
		{
			return -1;
		}
		Option button = options.get(top);
		for (int i = top - 1; i >= 0; i--)
		{
			Option option = options.get(i);
			if (option.getParam0() == button.getParam0() && option.getParam1() == button.getParam1()
				&& VIEW_TAG_TABS.equals(option.getText()))
			{
				return i;
			}
		}
		return -1;
	}
}

package com.ultimatebank.feature.storagesavings;

import com.ultimatebank.UltimateBankConfig;
import java.util.List;
import java.util.Objects;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.ConfigProfile;
import net.runelite.client.events.ConfigChanged;

/**
 * Keeps the settings that describe one character (its POH tiers, which storages it uses, STASH options) separate for
 * each character. RuneLite settings belong to the RuneLite profile, which several characters can share, so each
 * character's values are saved in its RS profile, and loaded into the settings when it logs in. The Configuration
 * panel therefore always shows the logged-in character's values. Must be called on the client thread.
 * <p>
 * Switching RuneLite profile (by hand, or the account's default profile at login) posts a ConfigChanged for every
 * setting that differs. Those aren't the user's choice, so they're ignored, and the character's values are loaded into
 * the new profile once the switch is done (call {@link #load()} on ProfileChanged).
 */
@Slf4j
@Singleton
class CharacterSettings
{
	/** Setting keys kept per character */
	static final List<String> KEYS = List.of(
		// POH tiers
		"storageSavingsTierFancyDressBox",
		"storageSavingsTierArmourCase",
		"storageSavingsTierMagicWardrobe",
		"storageSavingsTierCapeRack",
		"storageSavingsTierTreasureChest",
		// STASH options
		"storageSavingsStash",
		"storageSavingsStashBuiltOnly",
		// Locations
		"storageSavingsTreasureChest",
		"storageSavingsFancyDressBox",
		"storageSavingsMagicWardrobe",
		"storageSavingsArmourCase",
		"storageSavingsCapeRack",
		"storageSavingsToyBox",
		"storageSavingsBookcase",
		"storageSavingsPetHouse",
		"storageSavingsSpiceRack",
		"storageSavingsSeedVault",
		"storageSavingsToolLeprechaun",
		"storageSavingsTackleBox",
		"storageSavingsHuntsmansKit",
		"storageSavingsForestryKit",
		"storageSavingsSteelKeyRing",
		"storageSavingsMasterScrollBook",
		"storageSavingsFossilStorage",
		"storageSavingsElnockInquisitor",
		"storageSavingsFlamtaerBag",
		"storageSavingsNightmareZone",
		"storageSavingsMysteriousStranger"
	);

	/** RS profile key prefix for a character's copy of a setting */
	private static final String PREFIX = "character.";
	/** Saved for a setting left at its default (RuneLite doesn't store defaults) */
	static final String DEFAULT = "";

	private final ConfigManager configManager;
	/** Set while we write the settings ourselves, so those writes aren't saved back as the user's choice */
	private boolean applying;
	/** Id of the RuneLite profile the character's values were loaded into; it changes first during a profile switch */
	private volatile Long loadedProfile;

	@Inject
	CharacterSettings(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	/**
	 * Loads the logged-in character's values into the settings. A character seen for the first time keeps the
	 * current settings (what it used before settings were per character), which are saved as its own.
	 */
	void load()
	{
		loadedProfile = activeProfile();
		if (configManager.getRSProfileKey() == null)
		{
			return;
		}

		applying = true;
		try
		{
			int changed = 0;
			for (String key : KEYS)
			{
				String shared = configManager.getConfiguration(UltimateBankConfig.GROUP, key);
				String stored = configManager.getRSProfileConfiguration(UltimateBankConfig.GROUP, PREFIX + key);
				if (stored == null)
				{
					configManager.setRSProfileConfiguration(UltimateBankConfig.GROUP, PREFIX + key, toStored(shared));
					continue;
				}

				String wanted = fromStored(stored);
				if (!Objects.equals(wanted, shared))
				{
					changed++;
					if (wanted == null)
					{
						configManager.unsetConfiguration(UltimateBankConfig.GROUP, key);
					}
					else
					{
						configManager.setConfiguration(UltimateBankConfig.GROUP, key, wanted);
					}
				}
			}
			log.debug("Loaded per-character settings ({} differed)", changed);
		}
		finally
		{
			applying = false;
		}
	}

	/**
	 * Saves a per-character setting the user changed as the logged-in character's own.
	 */
	void onConfigChanged(ConfigChanged event)
	{
		if (applying || event.getProfile() != null || !UltimateBankConfig.GROUP.equals(event.getGroup())
			|| !KEYS.contains(event.getKey()) || configManager.getRSProfileKey() == null)
		{
			return;
		}
		if (!Objects.equals(loadedProfile, activeProfile()))
		{
			log.debug("Profile switch: not saving {} as this character's", event.getKey());
			return;
		}
		configManager.setRSProfileConfiguration(UltimateBankConfig.GROUP, PREFIX + event.getKey(),
			toStored(event.getNewValue()));
	}

	private Long activeProfile()
	{
		ConfigProfile profile = configManager.getProfile();
		return profile == null ? null : profile.getId();
	}

	/**
	 * @param value a setting's saved value, or null when it's at its default
	 */
	static String toStored(String value)
	{
		return value == null ? DEFAULT : value;
	}

	/**
	 * @return the setting value to apply, or null to reset it to its default
	 */
	static String fromStored(String stored)
	{
		return DEFAULT.equals(stored) ? null : stored;
	}
}

package com.ultimatebank.feature.storagesavings;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import net.runelite.client.util.Text;

/**
 * Resolves the user's ignore list (comma-separated item names, item IDs or {@code *} wildcards) into item IDs.
 * Names match ignoring case and whitespace, and a name shared by several items ignores all of them.
 */
final class IgnoreList
{
	private IgnoreList()
	{
	}

	/**
	 * @param namesToIds item IDs by {@link #normalize normalized} name, for every item that can be flagged
	 */
	static Set<Integer> resolve(String csv, Map<String, Set<Integer>> namesToIds)
	{
		if (csv == null || csv.isBlank())
		{
			return Collections.emptySet();
		}

		Set<Integer> ids = new HashSet<>();
		for (String entry : Text.fromCSV(csv))
		{
			String name = normalize(entry);
			if (name.isEmpty())
			{
				continue;
			}

			if (name.chars().allMatch(Character::isDigit))
			{
				try
				{
					ids.add(Integer.parseInt(name));
				}
				catch (NumberFormatException e)
				{
					// too long to be an item ID
				}
			}
			else if (name.indexOf('*') >= 0)
			{
				Pattern pattern = wildcard(name);
				namesToIds.forEach((itemName, itemIds) ->
				{
					if (pattern.matcher(itemName).matches())
					{
						ids.addAll(itemIds);
					}
				});
			}
			else
			{
				ids.addAll(namesToIds.getOrDefault(name, Collections.emptySet()));
			}
		}
		return ids;
	}

	/**
	 * @return whether the list has an entry naming exactly this item (by name or ID), i.e. one that
	 * {@link #remove} would take out
	 */
	static boolean containsExact(String csv, String itemName, int itemId)
	{
		String name = normalize(itemName);
		String id = String.valueOf(itemId);
		return Text.fromCSV(csv == null ? "" : csv).stream()
			.map(IgnoreList::normalize)
			.anyMatch(entry -> entry.equals(name) || entry.equals(id));
	}

	static String add(String csv, String itemName)
	{
		Collection<String> entries = new ArrayList<>(Text.fromCSV(csv == null ? "" : csv));
		entries.add(itemName);
		return Text.toCSV(entries);
	}

	/**
	 * Removes entries naming exactly this item. Wildcards that match it are left alone.
	 */
	static String remove(String csv, String itemName, int itemId)
	{
		String name = normalize(itemName);
		String id = String.valueOf(itemId);
		Collection<String> entries = new ArrayList<>(Text.fromCSV(csv == null ? "" : csv));
		entries.removeIf(entry ->
		{
			String normalized = normalize(entry);
			return normalized.equals(name) || normalized.equals(id);
		});
		return Text.toCSV(entries);
	}

	static String normalize(String name)
	{
		return name.toLowerCase(Locale.ROOT).replaceAll("\\s+", "");
	}

	private static Pattern wildcard(String normalized)
	{
		return Pattern.compile(Arrays.stream(normalized.split("\\*", -1))
			.map(Pattern::quote)
			.collect(Collectors.joining(".*")));
	}
}

package com.ultimatebank.feature.storagesavings;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import lombok.Value;

/**
 * Lays out the storable tab: one group per container, each starting on a new row with a blank title row above it
 * (the title itself is drawn by {@link StorableTitlesOverlay}). An item that fits several containers appears in each
 * group. Pure: no client access.
 */
final class StorableLayout
{
	static final int ROW = 8;
	private static final int EMPTY = -1;

	private StorableLayout()
	{
	}

	@Value
	static class Group
	{
		String title;
		List<Integer> itemIds;
	}

	@Value
	static class Result
	{
		/** Item ID by bank position, -1 for empty */
		int[] positions;
		/** Title by the (blank) row it's drawn on */
		Map<Integer, String> titleRows;
	}

	static Result build(List<Group> groups)
	{
		return build(groups, false);
	}

	/**
	 * @param keepEmpty whether a group with no items still gets its title (a focused group the player has emptied)
	 */
	static Result build(List<Group> groups, boolean keepEmpty)
	{
		List<Integer> positions = new ArrayList<>();
		Map<Integer, String> titles = new LinkedHashMap<>();
		for (Group group : groups)
		{
			if (group.getItemIds().isEmpty() && !keepEmpty)
			{
				continue;
			}
			padToRow(positions);
			titles.put(positions.size() / ROW, group.getTitle());
			for (int i = 0; i < ROW; i++)
			{
				positions.add(EMPTY);
			}
			positions.addAll(group.getItemIds());
		}
		return new Result(positions.stream().mapToInt(Integer::intValue).toArray(), Collections.unmodifiableMap(titles));
	}

	/**
	 * Sorts groups by their place in a previous order, so groups don't jump around while the player withdraws from
	 * them. Groups not in it go after, in their own order.
	 *
	 * @param previous titles in the order they were shown
	 */
	static List<Group> keepOrder(List<String> previous, List<Group> groups)
	{
		List<Group> sorted = new ArrayList<>(groups);
		sorted.sort(Comparator.comparingInt(g ->
		{
			int index = previous.indexOf(g.getTitle());
			return index == -1 ? Integer.MAX_VALUE : index;
		}));
		return sorted;
	}

	private static void padToRow(List<Integer> positions)
	{
		while (positions.size() % ROW != 0)
		{
			positions.add(EMPTY);
		}
	}
}

package com.ultimatebank.feature.storagesavings;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws each container's name and a divider line in the blank title rows of the grouped storable tab. Layouts can't
 * hold text, so titles are an overlay (approach from Bank Skill Sorting by Frailrain). Also remembers where each title
 * row was drawn, so a click on it can focus that group.
 */
@Singleton
class StorableTitlesOverlay extends Overlay
{
	private static final int ROW_HEIGHT = BankTagsPlugin.BANK_ITEM_HEIGHT + BankTagsPlugin.BANK_ITEM_Y_PADDING;
	private static final Color SHADOW = new Color(0, 0, 0, 170);
	private static final Color TITLE = new Color(255, 255, 255, 230);
	private static final Color LINE = new Color(160, 160, 160, 170);
	private static final Color HOVER = new Color(255, 200, 0, 240);
	private static final Color HINT = new Color(200, 200, 200, 200);

	private final Client client;
	private final StorageSavingsTagTab tagTab;
	/** Title rows drawn last frame, for clicks */
	private volatile List<TitleRow> drawnRows = Collections.emptyList();

	@Value
	private static class TitleRow
	{
		Rectangle bounds;
		String title;
	}

	@Inject
	StorableTitlesOverlay(Client client, StorageSavingsTagTab tagTab)
	{
		this.client = client;
		this.tagTab = tagTab;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		drawnRows = Collections.emptyList();
		Map<Integer, String> titles = tagTab.getTitleRows();
		if (titles.isEmpty())
		{
			return null;
		}

		Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (container == null || container.isHidden())
		{
			return null;
		}

		Rectangle clip = container.getBounds();
		Point origin = container.getCanvasLocation();
		int left = origin.getX() + BankTagsPlugin.BANK_ITEM_START_X;
		int right = clip.x + clip.width - 12;
		graphics.setFont(FontManager.getRunescapeBoldFont());
		Point mouse = client.getMouseCanvasPosition();
		String focus = tagTab.getFocus();
		List<TitleRow> rows = new ArrayList<>();

		for (Map.Entry<Integer, String> entry : titles.entrySet())
		{
			int rowTop = origin.getY() + BankTagsPlugin.BANK_ITEM_START_Y + entry.getKey() * ROW_HEIGHT - container.getScrollY();
			int lineY = rowTop + ROW_HEIGHT / 2;
			// Skip rows scrolled out of the bank's visible area
			if (lineY < clip.y + 6 || lineY > clip.y + clip.height - 4)
			{
				continue;
			}

			String title = entry.getValue();
			// From where the items start: the tag tabs to the left of them must still take their own clicks
			Rectangle bounds = new Rectangle(left, rowTop, clip.x + clip.width - left, ROW_HEIGHT).intersection(clip);
			rows.add(new TitleRow(bounds, title));
			boolean hovered = mouse != null && bounds.contains(mouse.getX(), mouse.getY());

			int baseline = lineY + graphics.getFontMetrics().getAscent() / 2 - 1;
			graphics.setColor(SHADOW);
			graphics.drawString(title, left + 1, baseline + 1);
			graphics.setColor(hovered ? HOVER : TITLE);
			graphics.drawString(title, left, baseline);
			int textEnd = left + graphics.getFontMetrics().stringWidth(title);

			String hint = focus != null ? "click to show all" : hovered ? "click to show only this" : null;
			if (hint != null)
			{
				graphics.setFont(FontManager.getRunescapeSmallFont());
				graphics.setColor(SHADOW);
				graphics.drawString(hint, textEnd + 9, baseline + 1);
				graphics.setColor(HINT);
				graphics.drawString(hint, textEnd + 8, baseline);
				textEnd += 8 + graphics.getFontMetrics().stringWidth(hint);
				graphics.setFont(FontManager.getRunescapeBoldFont());
			}

			int lineStart = textEnd + 8;
			if (right > lineStart)
			{
				graphics.setColor(LINE);
				graphics.drawLine(lineStart, lineY, right, lineY);
			}
		}
		drawnRows = rows;
		return null;
	}

	/**
	 * @return the title of the group whose title row is at this canvas point, or null
	 */
	String titleAt(java.awt.Point point)
	{
		for (TitleRow row : drawnRows)
		{
			if (row.getBounds().contains(point))
			{
				return row.getTitle();
			}
		}
		return null;
	}
}

