/**
 * Flags banked items that could be stored elsewhere (POH storage, tackle box, STASH units, ...) and ranks
 * storage locations by how many bank slots they would free. Ported from Wasted Bank Space; see
 * docs/features/storage-savings.md.
 */
@Slf4j
@Singleton
public class StorageSavingsFeature implements BankFeature
{
	private static final String KEY_PREFIX = "storageSavings";
	private static final String STASH_ROW = "STASH units";
	/** Tooltips list at most this many STASH units per item */
	private static final int MAX_STASH_IN_TOOLTIP = 3;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ItemManager itemManager;

	@Inject
	private UltimateBankConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private StorageSavingsOverlay overlay;

	@Inject
	private StorageSavingsTagTab tagTab;

	@Inject
	private StorableTitlesOverlay titlesOverlay;

	@Inject
	private StorageSavingsState state;

	@Inject
	private StashTracker stashTracker;

	private StorageSavingsPanel panel;
	private NavigationButton navButton;

	@Inject
	private StorageSnapshots snapshots;

	@Inject
	private PohTiers pohTiers;

	@Inject
	private SettingsOpener settingsOpener;

	@Inject
	private CharacterSettings characterSettings;

	private final Consumer<SnapshotLocation> snapshotListener = this::onSnapshotsChanged;

	/** Clicks on a storable tab group title show only that group */
	private final MouseAdapter titleClicks = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent event)
		{
			return onTitleMouse(event, true);
		}

		@Override
		public MouseEvent mouseReleased(MouseEvent event)
		{
			return onTitleMouse(event, false);
		}

		@Override
		public MouseEvent mouseClicked(MouseEvent event)
		{
			return onTitleMouse(event, false);
		}
	};

	/** Non-placeholder item IDs in the bank, or null until the bank has been seen */
	private Set<Integer> bankItems;
	/** When the saved bank snapshot behind {@link #bankItems} was taken, or 0 if the bank was seen live */
	private long bankSnapshotAt;
	/** Real Construction level the upgrade hints were worked out for */
	private int constructionLevel;
	/** Every storable item's ID by normalized name, built on first use */
	private Map<String, Set<Integer>> namesToIds;

	@Override
	public boolean isEnabled(UltimateBankConfig config)
	{
		return config.storageSavingsEnabled();
	}

	@Override
	public void startUp()
	{
		characterSettings.load();
		overlayManager.add(overlay);
		overlayManager.add(titlesOverlay);
		mouseManager.registerMouseListener(titleClicks);

		panel = new StorageSavingsPanel(settingsOpener::open);
		navButton = NavigationButton.builder()
			.tooltip("Ultimate Bank Savings")
			.icon(createIcon())
			.priority(8)
			.panel(panel)
			.build();
		syncPanel();

		tagTab.setBankOpen(client.getWidget(InterfaceID.Bankmain.ITEMS) != null);
		tagTab.sync();
		stashTracker.load();

		snapshots.addListener(snapshotListener);
		ItemContainer bank = client.getItemContainer(InventoryID.BANK);
		if (bank != null)
		{
			readBank(bank);
		}
		recompute();
	}

	@Override
	public void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(titlesOverlay);
		mouseManager.unregisterMouseListener(titleClicks);
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;
		snapshots.removeListener(snapshotListener);
		tagTab.remove();
		state.set(StorageSavingsState.Results.EMPTY);
		bankItems = null;
		bankSnapshotAt = 0;
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.BANK)
		{
			if (readBank(event.getItemContainer()))
			{
				recompute();
			}
		}
		else if (config.storageSavingsStash())
		{
			stashTracker.onItemContainerChanged(event);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		characterSettings.onConfigChanged(event);
		if (!UltimateBankConfig.GROUP.equals(event.getGroup()) || !event.getKey().startsWith(KEY_PREFIX))
		{
			return;
		}

		switch (event.getKey())
		{
			case "storageSavingsPanel":
				syncPanel();
				return;
			case "storageSavingsTagTab":
			case "storageSavingsTagTabGroups":
				clientThread.invokeLater(tagTab::sync);
				return;
			case "storageSavingsMarker":
			case "storageSavingsMarkerColor":
			case "storageSavingsMarkerStyle":
			case "storageSavingsMarkerCorner":
			case "storageSavingsMarkerSize":
			case "storageSavingsMarkerThickness":
				// read live by the overlay
				return;
			case "storageSavingsStash":
				clientThread.invokeLater(() ->
				{
					stashTracker.load();
					recompute();
				});
				return;
			default:
				// STASH state and tag tab bookkeeping are stored under this prefix too; recomputing for them is harmless
				clientThread.invokeLater(this::recompute);
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		// The new character's tiers, locations and STASH options
		characterSettings.load();
		bankItems = null;
		stashTracker.load();
		recompute();
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			tagTab.setBankOpen(true);
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			tagTab.setBankOpen(false);
		}
	}

	/**
	 * Toggles the focus on a left-click on a storable tab title row, and keeps the game from seeing that click.
	 * The row is empty bank space, so the click would do nothing in game anyway.
	 */
	private MouseEvent onTitleMouse(MouseEvent event, boolean pressed)
	{
		if (event.getButton() != MouseEvent.BUTTON1)
		{
			return event;
		}
		String title = titlesOverlay.titleAt(event.getPoint());
		if (title == null)
		{
			return event;
		}
		if (pressed)
		{
			clientThread.invoke(() -> tagTab.toggleFocus(title));
		}
		event.consume();
		return event;
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		// A RuneLite profile switch replaced the settings: put the character's own back
		clientThread.invoke(characterSettings::load);
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		if (bankItems == null || !client.isKeyPressed(KeyCode.KC_SHIFT))
		{
			return;
		}

		MenuEntry[] entries = event.getMenuEntries();
		for (int i = entries.length - 1; i >= 0; i--)
		{
			Widget widget = entries[i].getWidget();
			if (widget == null || widget.getParentId() != InterfaceID.Bankmain.ITEMS)
			{
				continue;
			}

			int itemId = widget.getItemId();
			String name = itemManager.getItemComposition(itemId).getName();
			String ignored = config.storageSavingsIgnored();
			boolean listed = IgnoreList.containsExact(ignored, name, itemId);
			if (listed || state.getFlagged().containsKey(itemId))
			{
				client.getMenu().createMenuEntry(i)
					.setOption(listed ? "Unignore storable" : "Ignore storable")
					.setTarget(entries[i].getTarget())
					.setType(MenuAction.RUNELITE)
					.onClick(e -> config.storageSavingsIgnored(
						listed ? IgnoreList.remove(ignored, name, itemId) : IgnoreList.add(ignored, name)));
			}
			return;
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		// Costume room furniture (or its empty build space) tells us which tier is built
		pohTiers.seen(event.getGameObject().getId());
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (pohTiers.applySeen())
		{
			recompute();
		}

		if (config.storageSavingsStash() && stashTracker.onGameTick())
		{
			recompute();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		// Upgrade hints only suggest tiers the player can build
		if (event.getSkill() == Skill.CONSTRUCTION && event.getLevel() != constructionLevel)
		{
			recompute();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (config.storageSavingsStash())
		{
			stashTracker.onGameStateChanged(event);
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (config.storageSavingsStash())
		{
			stashTracker.onVarbitChanged(event);
		}
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (config.storageSavingsStash())
		{
			stashTracker.onScriptPreFired(event);
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (config.storageSavingsStash())
		{
			stashTracker.onMenuOptionClicked(event);
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (config.storageSavingsStash())
		{
			stashTracker.onChatMessage(event);
			recompute();
		}
	}

	/**
	 * @return whether the bank's contents changed
	 */
	private boolean readBank(ItemContainer bank)
	{
		Set<Integer> items = new HashSet<>();
		for (Item item : bank.getItems())
		{
			int itemId = item.getId();
			if (itemId <= 0 || itemManager.getItemComposition(itemId).getPlaceholderTemplateId() != -1)
			{
				continue;
			}
			items.add(itemId);
		}

		boolean wasSnapshot = bankSnapshotAt != 0;
		bankSnapshotAt = 0;
		if (items.equals(bankItems) && !wasSnapshot)
		{
			return false;
		}
		bankItems = items;
		return true;
	}

	/**
	 * A bank or POH snapshot was recorded (location), or the account's snapshots were loaded (null).
	 */
	private void onSnapshotsChanged(SnapshotLocation location)
	{
		// A bank snapshot taken while we're watching the live bank is the data we already recomputed from
		boolean bankLive = bankItems != null && bankSnapshotAt == 0;
		if (location != SnapshotLocation.BANK || !bankLive)
		{
			recompute();
		}
	}

	/**
	 * Uses the saved bank snapshot until the bank is seen live this session, if enabled.
	 */
	private void useBankSnapshotIfNeeded()
	{
		boolean live = bankItems != null && bankSnapshotAt == 0;
		if (live)
		{
			return;
		}

		Snapshot bank = config.storageSavingsUseSnapshots() ? snapshots.latest(SnapshotLocation.BANK) : null;
		if (bank == null)
		{
			bankItems = null;
			bankSnapshotAt = 0;
			return;
		}

		Set<Integer> items = new HashSet<>();
		for (int itemId : bank.getQuantities().keySet())
		{
			if (itemManager.getItemComposition(itemId).getPlaceholderTemplateId() == -1)
			{
				items.add(itemId);
			}
		}
		bankItems = items;
		bankSnapshotAt = bank.getTakenAt();
	}

	/**
	 * Storage stacks, so copies already stored never stop another going in; this is just shown as information.
	 *
	 * @return how many of the item the location's snapshot shows stored, or 0 if none or unknown
	 */
	private int storedCount(StorageLocation location, int itemId)
	{
		SnapshotLocation snapshotLocation = location.getSnapshotLocation();
		Snapshot stored = snapshotLocation == null || !config.storageSavingsUseSnapshots()
			? null : snapshots.latest(snapshotLocation);
		return stored == null ? 0 : stored.getQuantities().getOrDefault(itemId, 0);
	}

	/**
	 * Recalculates flagged items and the ranking from the last seen bank. Must be called on the client thread.
	 */
	private void recompute()
	{
		useBankSnapshotIfNeeded();
		if (bankItems == null)
		{
			publish(StorageSavingsState.Results.EMPTY);
			return;
		}

		Set<Integer> ignored = IgnoreList.resolve(config.storageSavingsIgnored(), namesToIds());
		boolean keepBis = config.storageSavingsKeepBis();
		boolean stash = config.storageSavingsStash();
		boolean stashBuiltOnly = config.storageSavingsStashBuiltOnly();

		Map<Integer, List<String>> flagged = new HashMap<>();
		Map<String, List<Integer>> itemsByLocation = new LinkedHashMap<>();
		Set<String> pohLocations = new HashSet<>();
		Set<Integer> alsoStored = new HashSet<>();
		Map<StorageLocation, TierResult> tiers = planTiers(ignored, keepBis);

		for (int itemId : bankItems)
		{
			if (ignored.contains(itemId) || (keepBis && StorageLocation.isBis(itemId)))
			{
				continue;
			}

			List<String> where = new ArrayList<>();
			for (StorageLocation location : StorageLocation.forItem(itemId))
			{
				TierResult tier = tiers.get(location);
				if (location.isEnabled(config) && (tier == null || tier.fits.contains(itemId)))
				{
					int stored = storedCount(location, itemId);
					if (stored > 0)
					{
						alsoStored.add(itemId);
					}
					where.add(stored > 0 ? location.getDisplayName() + " (" + stored + " stored)" : location.getDisplayName());
					itemsByLocation.computeIfAbsent(location.getDisplayName(), k -> new ArrayList<>()).add(itemId);
					if (location.isPoh())
					{
						pohLocations.add(location.getDisplayName());
					}
				}
			}

			if (stash)
			{
				List<StashUnit> units = StashUnit.forItem(itemId).stream()
					.filter(unit -> !stashBuiltOnly || (stashTracker.isBuilt(unit) && !stashTracker.isFilled(unit)))
					.collect(Collectors.toList());
				if (!units.isEmpty())
				{
					units.stream().limit(MAX_STASH_IN_TOOLTIP).forEach(unit -> where.add(unit.getLocation()));
					if (units.size() > MAX_STASH_IN_TOOLTIP)
					{
						where.add("...and " + (units.size() - MAX_STASH_IN_TOOLTIP) + " more STASH units");
					}
					itemsByLocation.computeIfAbsent(STASH_ROW, k -> new ArrayList<>()).add(itemId);
				}
			}

			if (!where.isEmpty())
			{
				flagged.put(itemId, List.copyOf(where));
			}
		}

		// Storages that hold nothing now but would after an upgrade still get a row, for the upgrade hint
		Map<String, TierResult> tiersByName = new HashMap<>();
		tiers.forEach((location, result) ->
		{
			tiersByName.put(location.getDisplayName(), result);
			if (result.nextTierExtra > 0)
			{
				itemsByLocation.computeIfAbsent(location.getDisplayName(), k -> new ArrayList<>());
				pohLocations.add(location.getDisplayName());
			}
		});

		Map<Integer, String> names = new HashMap<>();
		List<StorageSavingsState.LocationSavings> ranking = itemsByLocation.entrySet().stream()
			.map(e ->
			{
				List<Integer> ids = new ArrayList<>(e.getValue());
				ids.forEach(id -> names.computeIfAbsent(id, k -> itemManager.getItemComposition(k).getName()));
				ids.sort(Comparator.comparing(names::get, String.CASE_INSENSITIVE_ORDER));
				TierResult tier = tiersByName.get(e.getKey());
				return new StorageSavingsState.LocationSavings(e.getKey(), pohLocations.contains(e.getKey()),
					ids.stream().map(names::get).collect(Collectors.toList()), List.copyOf(ids),
					tier == null ? null : tier.label, tier == null ? null : tier.nextTier,
					tier == null ? 0 : tier.nextTierExtra);
			})
			.sorted(Comparator.comparingInt((StorageSavingsState.LocationSavings l) -> l.getItemNames().size()).reversed()
				.thenComparing(Comparator.comparingInt(StorageSavingsState.LocationSavings::getNextTierExtra).reversed())
				.thenComparing(StorageSavingsState.LocationSavings::getName))
			.collect(Collectors.toList());

		log.debug("{} storable items in bank across {} locations", flagged.size(), ranking.size());
		publish(new StorageSavingsState.Results(true, bankSnapshotAt, alsoStored.size(), Map.copyOf(flagged), ranking));
	}

	/**
	 * Applies each tiered POH storage's capacity at the built tier: which banked items fit, and what the best tier
	 * the player's Construction level can build would add.
	 */
	private Map<StorageLocation, TierResult> planTiers(Set<Integer> ignored, boolean keepBis)
	{
		Map<StorageLocation, TierResult> results = new HashMap<>();
		constructionLevel = client.getRealSkillLevel(Skill.CONSTRUCTION);
		for (PohStorage storage : PohStorage.values())
		{
			StorageLocation location = storage.getLocation();
			if (!location.isEnabled(config))
			{
				continue;
			}

			Set<Integer> candidates = new HashSet<>();
			for (int itemId : bankItems)
			{
				if (!ignored.contains(itemId) && !(keepBis && StorageLocation.isBis(itemId))
					&& StorageLocation.forItem(itemId).contains(location))
				{
					candidates.add(itemId);
				}
			}

			int tier = pohTiers.tier(storage);
			if (tier == PohTiers.UNKNOWN)
			{
				results.put(location, new TierResult(candidates, "tier unknown", null, 0));
				continue;
			}

			List<TierPlanner.StorageSet> sets = pohTiers.sets(storage);
			Snapshot snapshot = config.storageSavingsUseSnapshots() ? snapshots.latest(location.getSnapshotLocation()) : null;
			Set<Integer> stored = snapshot == null ? Set.of() : snapshot.getQuantities().keySet();
			List<PohStorage.Tier> storageTiers = storage.getTiers();

			Set<Integer> fits = tier == PohStorage.NOT_BUILT ? Set.of()
				: TierPlanner.fits(storage.getLimit(), storageTiers.get(tier).getCapacity(), sets, candidates, stored);
			String nextTier = null;
			int extra = 0;
			// Only an upgrade the player has the Construction level for can save space
			int upgrade = storage.bestUpgrade(tier, constructionLevel);
			if (upgrade != PohStorage.NOT_BUILT)
			{
				PohStorage.Tier next = storageTiers.get(upgrade);
				nextTier = next.getName();
				extra = TierPlanner.fits(storage.getLimit(), next.getCapacity(), sets, candidates, stored).size() - fits.size();
			}
			String label = tier == PohStorage.NOT_BUILT ? "not built" : storageTiers.get(tier).getName();
			results.put(location, new TierResult(fits, label, nextTier, Math.max(0, extra)));
		}
		return results;
	}

	@Value
	private static class TierResult
	{
		Set<Integer> fits;
		String label;
		String nextTier;
		int nextTierExtra;
	}

	private void publish(StorageSavingsState.Results results)
	{
		state.set(results);
		tagTab.setItems(results.getFlagged().keySet(), results.getRanking());
		StorageSavingsPanel panel = this.panel;
		if (panel != null)
		{
			SwingUtilities.invokeLater(() -> panel.update(results));
		}
	}

	private Map<String, Set<Integer>> namesToIds()
	{
		if (namesToIds == null)
		{
			Set<Integer> storable = new HashSet<>(StorageLocation.allItemIds());
			storable.addAll(StashUnit.allItemIds());
			Map<String, Set<Integer>> names = new HashMap<>();
			for (int itemId : storable)
			{
				String name = IgnoreList.normalize(itemManager.getItemComposition(itemId).getName());
				names.computeIfAbsent(name, k -> new HashSet<>()).add(itemId);
			}
			namesToIds = names;
		}
		return namesToIds;
	}

	private void syncPanel()
	{
		if (navButton == null)
		{
			return;
		}
		if (config.storageSavingsPanel())
		{
			clientToolbar.addNavigation(navButton);
		}
		else
		{
			clientToolbar.removeNavigation(navButton);
		}
	}

	/**
	 * A small chest icon, drawn rather than shipped as a PNG.
	 */
	private static BufferedImage createIcon()
	{
		BufferedImage icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = icon.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(120, 72, 32));
		g.fillRoundRect(1, 4, 14, 11, 3, 3);
		g.setColor(new Color(160, 100, 48));
		g.fillRoundRect(1, 2, 14, 5, 3, 3);
		g.setColor(new Color(255, 200, 0));
		g.fillRect(7, 6, 2, 4);
		g.dispose();
		return icon;
	}
}

package com.ultimatebank.feature.storagesavings;

import com.ultimatebank.UltimateBankConfig;
import com.ultimatebank.feature.storagesavings.marker.MarkerGeometry;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.Stroke;
import java.awt.image.BufferedImage;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * Marks flagged bank items in the configured style (item outline, box outline or corner triangle), and
 * names where they can be stored on hover.
 */
@Singleton
class StorageSavingsOverlay extends WidgetItemOverlay
{
	private static final Color EDGE = Color.BLACK;
	/** Outline images kept; one per item, quantity, colour and thickness on screen */
	private static final int OUTLINE_CACHE_SIZE = 300;

	private final Client client;
	private final TooltipManager tooltipManager;
	private final UltimateBankConfig config;
	private final StorageSavingsState state;
	private final ItemManager itemManager;

	private final Map<String, BufferedImage> outlines = new LinkedHashMap<>(16, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<String, BufferedImage> eldest)
		{
			return size() > OUTLINE_CACHE_SIZE;
		}
	};

	@Inject
	StorageSavingsOverlay(Client client, TooltipManager tooltipManager, UltimateBankConfig config, StorageSavingsState state,
		ItemManager itemManager)
	{
		this.client = client;
		this.tooltipManager = tooltipManager;
		this.config = config;
		this.state = state;
		this.itemManager = itemManager;
		showOnBank();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem itemWidget)
	{
		if (!config.storageSavingsMarker() || itemWidget.getWidget().getParentId() != InterfaceID.Bankmain.ITEMS)
		{
			return;
		}

		List<String> locations = state.getFlagged().get(itemId);
		if (locations == null)
		{
			return;
		}

		Rectangle bounds = itemWidget.getCanvasBounds();
		Color color = config.storageSavingsMarkerColor();
		switch (config.storageSavingsMarkerStyle())
		{
			case ITEM_OUTLINE:
				drawItemOutline(graphics, itemId, itemWidget.getQuantity(), bounds, color);
				break;
			case BOX_OUTLINE:
				drawBox(graphics, bounds, color);
				break;
			default:
				drawTriangle(graphics, bounds, color);
				break;
		}

		Point mouse = client.getMouseCanvasPosition();
		if (bounds.contains(mouse.getX(), mouse.getY()))
		{
			tooltipManager.add(new Tooltip("Can be stored in:</br>" + String.join("</br>", locations)));
		}
	}

	private void drawTriangle(Graphics2D graphics, Rectangle bounds, Color color)
	{
		Polygon marker = MarkerGeometry.triangle(bounds, config.storageSavingsMarkerCorner(), config.storageSavingsMarkerSize());
		graphics.setColor(color);
		graphics.fill(marker);
		graphics.setColor(EDGE);
		graphics.draw(marker);
	}

	private void drawBox(Graphics2D graphics, Rectangle bounds, Color color)
	{
		int t = config.storageSavingsMarkerThickness();
		Stroke previous = graphics.getStroke();
		graphics.setColor(color);
		graphics.setStroke(new BasicStroke(t));
		// Inset by half the stroke so the box stays inside the slot
		graphics.drawRect(bounds.x + t / 2, bounds.y + t / 2, bounds.width - t, bounds.height - t);
		graphics.setStroke(previous);
	}

	private void drawItemOutline(Graphics2D graphics, int itemId, int quantity, Rectangle bounds, Color color)
	{
		int thickness = config.storageSavingsMarkerThickness();
		String key = itemId + ":" + quantity + ":" + color.getRGB() + ":" + thickness;
		BufferedImage outline = outlines.computeIfAbsent(key, k -> thicken(itemManager.getItemOutline(itemId, quantity, color), thickness));
		int pad = thickness - 1;
		graphics.drawImage(outline, bounds.x - pad, bounds.y - pad, null);
	}

	/**
	 * @return the 1px outline stamped at every offset up to thickness - 1, on a canvas padded to fit
	 */
	private static BufferedImage thicken(BufferedImage outline, int thickness)
	{
		if (thickness <= 1)
		{
			return outline;
		}
		int pad = thickness - 1;
		BufferedImage thick = new BufferedImage(outline.getWidth() + pad * 2, outline.getHeight() + pad * 2,
			BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = thick.createGraphics();
		for (int dx = -pad; dx <= pad; dx++)
		{
			for (int dy = -pad; dy <= pad; dy++)
			{
				g.drawImage(outline, pad + dx, pad + dy, null);
			}
		}
		g.dispose();
		return thick;
	}
}

package com.ultimatebank.feature.storagesavings;

import com.ultimatebank.core.snapshots.Snapshot;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.HashSet;
import java.util.Set;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Ranks storage locations by how many bank slots they would free. Click a location to list its items.
 * Must only be touched on the Swing thread.
 */
class StorageSavingsPanel extends PluginPanel
{
	private static final Color UPGRADE = new Color(120, 200, 120);

	private final JLabel summary = new JLabel();
	private final JPanel ranking = new JPanel();
	/** Locations the user has expanded, kept across updates */
	private final Set<String> expanded = new HashSet<>();

	private StorageSavingsState.Results results = StorageSavingsState.Results.EMPTY;

	/**
	 * @param openSettings opens the plugin settings, where storage locations and POH tiers are chosen
	 */
	StorageSavingsPanel(Runnable openSettings)
	{
		setLayout(new BorderLayout(0, 8));
		setBorder(new EmptyBorder(10, 10, 10, 10));

		JPanel header = new JPanel(new BorderLayout(0, 4));
		JLabel title = new JLabel("Ultimate Bank Savings");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		header.add(title, BorderLayout.NORTH);
		summary.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		header.add(summary, BorderLayout.CENTER);
		JButton settings = new JButton("Edit storage locations & tiers");
		settings.setToolTipText("Opens the settings: expand \"Bank Savings: Locations\" or \"Bank Savings: Tiers\"");
		settings.setFocusPainted(false);
		settings.addActionListener(e -> openSettings.run());
		header.add(settings, BorderLayout.SOUTH);
		add(header, BorderLayout.NORTH);

		ranking.setLayout(new BoxLayout(ranking, BoxLayout.Y_AXIS));
		add(ranking, BorderLayout.CENTER);

		rebuild();
	}

	void update(StorageSavingsState.Results results)
	{
		this.results = results;
		rebuild();
	}

	private void rebuild()
	{
		ranking.removeAll();

		if (!results.isBankSeen())
		{
			summary.setText("<html>Open your bank to scan it.</html>");
		}
		else
		{
			int count = results.getFlagged().size();
			String text = count == 0
				? "Nothing in your bank could be stored elsewhere."
				: count + (count == 1 ? " item" : " items") + " could be stored elsewhere. Click a location to see its items.";
			if (results.getAlreadyStored() > 0)
			{
				text += "<br>" + results.getAlreadyStored() + " already have copies stored in your POH.";
			}
			if (results.getBankSnapshotAt() > 0)
			{
				text += "<br><i>From your bank as last seen " + Snapshot.ago(results.getBankSnapshotAt()) + ".</i>";
			}
			summary.setText("<html>" + text + "</html>");
			for (StorageSavingsState.LocationSavings location : results.getRanking())
			{
				ranking.add(row(location));
			}
		}

		ranking.revalidate();
		ranking.repaint();
	}

	/**
	 * @return e.g. "Oak · +3 with Teak", "not built · +5 with Oak", "tier unknown: visit your costume room", or null
	 */
	private static String tierText(StorageSavingsState.LocationSavings location)
	{
		String tier = location.getTier();
		if (tier == null)
		{
			return null;
		}
		if ("tier unknown".equals(tier))
		{
			return "tier unknown: visit your costume room";
		}
		if (location.getNextTierExtra() > 0)
		{
			return tier + " · +" + location.getNextTierExtra() + " with " + location.getNextTier();
		}
		return tier;
	}

	private JPanel row(StorageSavingsState.LocationSavings location)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 4, 0, ColorScheme.DARK_GRAY_COLOR),
			new EmptyBorder(6, 8, 6, 8)));

		int slots = location.getItemNames().size();
		JLabel name = new JLabel(location.getName());
		name.setForeground(location.isPoh() ? ColorScheme.BRAND_ORANGE : Color.WHITE);
		JLabel count = new JLabel(slots + (slots == 1 ? " slot" : " slots"));
		count.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		JPanel heading = new JPanel(new BorderLayout());
		heading.setOpaque(false);
		heading.add(name, BorderLayout.WEST);
		heading.add(count, BorderLayout.EAST);

		String tierText = tierText(location);
		if (tierText != null)
		{
			JLabel tier = new JLabel(tierText);
			tier.setFont(FontManager.getRunescapeSmallFont());
			tier.setForeground(location.getNextTierExtra() > 0 ? UPGRADE : ColorScheme.LIGHT_GRAY_COLOR);
			heading.add(tier, BorderLayout.SOUTH);
		}
		row.add(heading, BorderLayout.NORTH);

		boolean open = expanded.contains(location.getName());
		if (open)
		{
			JPanel items = new JPanel();
			items.setLayout(new BoxLayout(items, BoxLayout.Y_AXIS));
			items.setOpaque(false);
			items.setBorder(new EmptyBorder(4, 6, 0, 0));
			for (String itemName : location.getItemNames())
			{
				JLabel item = new JLabel(itemName);
				item.setFont(FontManager.getRunescapeSmallFont());
				item.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
				items.add(item);
			}
			row.add(items, BorderLayout.CENTER);
		}

		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (!expanded.remove(location.getName()))
				{
					expanded.add(location.getName());
				}
				rebuild();
			}
		});
		row.setToolTipText(location.isPoh() ? "Player-owned house storage" : null);
		row.setAlignmentX(LEFT_ALIGNMENT);
		return row;
	}
}

package com.ultimatebank.feature.storagesavings;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import javax.inject.Singleton;
import lombok.Value;

/**
 * The latest storage savings results, shared by the feature (writer, client thread), the overlay
 * (client thread) and the panel (Swing thread). Results are replaced whole, never modified.
 */
@Singleton
class StorageSavingsState
{
	private volatile Results results = Results.EMPTY;

	Results get()
	{
		return results;
	}

	void set(Results results)
	{
		this.results = results;
	}

	/**
	 * @return location names by flagged item ID
	 */
	Map<Integer, List<String>> getFlagged()
	{
		return results.getFlagged();
	}

	@Value
	static class Results
	{
		static final Results EMPTY = new Results(false, 0, 0, Collections.emptyMap(), Collections.emptyList());

		/** Whether bank contents are known (seen this session, or from a saved snapshot) */
		boolean bankSeen;
		/** When the saved bank snapshot in use was taken, or 0 if the bank was seen live this session */
		long bankSnapshotAt;
		/** Flagged items that a suggested POH storage already holds copies of (shown for information) */
		int alreadyStored;
		/** Location names by flagged item ID */
		Map<Integer, List<String>> flagged;
		/** Storage locations by bank slots they would free, most first */
		List<LocationSavings> ranking;
	}

	@Value
	static class LocationSavings
	{
		String name;
		/** Whether this is a player-owned house build */
		boolean poh;
		/** Names of the flagged items it could hold, sorted */
		List<String> itemNames;
		/** IDs of the same items, in the same order */
		List<Integer> itemIds;
		/** Built tier ("Oak", "not built", "tier unknown"), or null if the location has no tiers */
		String tier;
		/** Best tier above the built one that the player can build, or null if there's none (or the tier is unknown) */
		String nextTier;
		/** Extra items the next tier would take */
		int nextTierExtra;
	}
}

package com.ultimatebank.feature.storagesavings;

import com.google.common.base.Strings;
import com.ultimatebank.UltimateBankConfig;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.Layout;
import net.runelite.client.plugins.banktags.tabs.LayoutManager;
import net.runelite.client.util.Text;

/**
 * A virtual bank tag holding every flagged item, plus a tag tab to open it. Built on core bank tags:
 * the tag is registered with {@link TagManager}, and the tab is added to the Bank Tags plugin's tab list.
 * Adapted from the "wasted" tag tab by Brettgod1355 (Wasted Bank Space PR #136). When grouping is on, the tab gets a
 * core layout with one titled group per container (see {@link StorableLayout}). While the bank is open the groups
 * keep their order, so they don't jump around as the player withdraws, and clicking a title shows only that group.
 * All methods must be called on the client thread.
 */
@Slf4j
@Singleton
class StorageSavingsTagTab
{
	static final String TAG_NAME = "storable";

	private static final int ICON_ITEM_ID = ItemID.POH_FLATPACK_TREASURE_CHEST3;
	/** Set when we added the tab, so we only ever remove a tab we created and never a user's own */
	private static final String TAB_CREATED_KEY = "storageSavingsTagTabCreated";

	private final ConfigManager configManager;
	private final TagManager tagManager;
	private final BankTagsService bankTagsService;
	private final UltimateBankConfig config;
	private final LayoutManager layoutManager;

	// Replaced whole, never modified, so the registered tag always reads a consistent set
	private volatile Set<Integer> items = Collections.emptySet();
	/** What the tag shows: all flagged items, or the focused group's */
	private volatile Set<Integer> visible = Collections.emptySet();
	private List<StorageSavingsState.LocationSavings> groups = Collections.emptyList();
	/** Titles by layout row, read by the overlay; empty when the tab isn't grouped */
	private volatile Map<Integer, String> titleRows = Collections.emptyMap();
	private boolean registered;
	private boolean bankOpen;
	/** Group titles in the order shown; held while the bank is open */
	private List<String> shownOrder = Collections.emptyList();
	/** The only group shown, or null for all */
	private volatile String focus;

	@Inject
	StorageSavingsTagTab(ConfigManager configManager, TagManager tagManager, BankTagsService bankTagsService,
		UltimateBankConfig config, LayoutManager layoutManager)
	{
		this.layoutManager = layoutManager;
		this.configManager = configManager;
		this.tagManager = tagManager;
		this.bankTagsService = bankTagsService;
		this.config = config;
	}

	/**
	 * Adds or removes the tag and tab to match config.
	 */
	void sync()
	{
		if (config.storageSavingsTagTab())
		{
			if (!registered)
			{
				tagManager.registerTag(TAG_NAME, itemId -> visible.contains(itemId));
				registered = true;
			}
			addTab();
			saveLayout();
		}
		else
		{
			remove();
		}
		refreshIfOpen();
	}

	void remove()
	{
		if (registered)
		{
			tagManager.unregisterTag(TAG_NAME);
			registered = false;
		}
		removeTab();
		titleRows = Collections.emptyMap();
		focus = null;
		if (TAG_NAME.equals(bankTagsService.getActiveTag()))
		{
			bankTagsService.closeBankTag();
		}
	}

	/**
	 * @param ranking containers by bank slots freed, most first, with the flagged items each could hold
	 */
	void setItems(Set<Integer> flaggedItems, List<StorageSavingsState.LocationSavings> ranking)
	{
		if (flaggedItems.equals(items) && ranking.equals(groups))
		{
			return;
		}
		items = Set.copyOf(flaggedItems);
		groups = List.copyOf(ranking);
		if (registered)
		{
			saveLayout();
		}
		refreshIfOpen();
	}

	/**
	 * The bank opened or closed. Closing it ends any focus and lets the groups take their ranked order again.
	 */
	void setBankOpen(boolean open)
	{
		if (open == bankOpen)
		{
			return;
		}
		bankOpen = open;
		if (!open)
		{
			focus = null;
			if (registered)
			{
				saveLayout();
			}
		}
	}

	/**
	 * Shows only the group with this title, or all groups again if it's already the only one shown.
	 */
	void toggleFocus(String title)
	{
		if (!registered)
		{
			return;
		}
		focus = title.equals(focus) ? null : title;
		log.debug("Storable tab focus: {}", focus);
		saveLayout();
		refreshIfOpen();
	}

	String getFocus()
	{
		return focus;
	}

	boolean isOpen()
	{
		return registered && TAG_NAME.equals(bankTagsService.getActiveTag());
	}

	/**
	 * Titles to draw, by layout row, while the storable tab is open.
	 */
	Map<Integer, String> getTitleRows()
	{
		return TAG_NAME.equals(bankTagsService.getActiveTag()) ? titleRows : Collections.emptyMap();
	}

	private void saveLayout()
	{
		if (!config.storageSavingsTagTabGroups())
		{
			focus = null;
			visible = items;
			// Only remove a grouped layout we made, not one the user arranged by hand
			if (!titleRows.isEmpty())
			{
				layoutManager.removeLayout(TAG_NAME);
				titleRows = Collections.emptyMap();
			}
			return;
		}

		List<StorableLayout.Group> all = groups.stream()
			.map(g -> new StorableLayout.Group(g.getName(), g.getItemIds()))
			.collect(Collectors.toList());
		if (bankOpen)
		{
			all = StorableLayout.keepOrder(shownOrder, all);
			List<String> order = new ArrayList<>(shownOrder);
			all.stream().map(StorableLayout.Group::getTitle).filter(t -> !order.contains(t)).forEach(order::add);
			shownOrder = order;
		}
		else
		{
			shownOrder = all.stream().map(StorableLayout.Group::getTitle).collect(Collectors.toList());
		}

		String focus = this.focus;
		StorableLayout.Result result;
		if (focus == null)
		{
			visible = items;
			result = StorableLayout.build(all);
		}
		else
		{
			StorableLayout.Group group = all.stream().filter(g -> g.getTitle().equals(focus)).findFirst()
				.orElse(new StorableLayout.Group(focus, List.of()));
			visible = Set.copyOf(group.getItemIds());
			result = StorableLayout.build(List.of(group), true);
		}
		layoutManager.saveLayout(new Layout(TAG_NAME, result.getPositions()));
		titleRows = result.getTitleRows();
	}

	private void addTab()
	{
		List<String> tabs = getTabNames();
		if (tabs.contains(TAG_NAME))
		{
			return;
		}

		tabs.add(TAG_NAME);
		configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_TABS_CONFIG, Text.toCSV(tabs));
		configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_ICON_PREFIX + TAG_NAME, ICON_ITEM_ID);
		configManager.setConfiguration(UltimateBankConfig.GROUP, TAB_CREATED_KEY, true);
		log.debug("Added bank tag tab '{}'", TAG_NAME);
	}

	private void removeTab()
	{
		if (!Boolean.TRUE.equals(configManager.getConfiguration(UltimateBankConfig.GROUP, TAB_CREATED_KEY, Boolean.class)))
		{
			return;
		}

		List<String> tabs = getTabNames();
		if (tabs.remove(TAG_NAME))
		{
			configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_TABS_CONFIG, Text.toCSV(tabs));
		}
		configManager.unsetConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_ICON_PREFIX + TAG_NAME);
		layoutManager.removeLayout(TAG_NAME);
		configManager.unsetConfiguration(UltimateBankConfig.GROUP, TAB_CREATED_KEY);
		log.debug("Removed bank tag tab '{}'", TAG_NAME);
	}

	private List<String> getTabNames()
	{
		String tabs = configManager.getConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_TABS_CONFIG);
		return new ArrayList<>(Text.fromCSV(Strings.nullToEmpty(tabs)));
	}

	/**
	 * Re-opens the tag if it's being viewed, so the bank shows the current flagged items.
	 */
	private void refreshIfOpen()
	{
		if (registered && TAG_NAME.equals(bankTagsService.getActiveTag()))
		{
			bankTagsService.openBankTag(TAG_NAME, BankTagsService.OPTION_ALLOW_MODIFICATIONS);
		}
	}
}

package com.ultimatebank.feature.storagesavings.data;

import com.ultimatebank.UltimateBankConfig;
import com.ultimatebank.core.snapshots.SnapshotLocation;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.function.Predicate;
