		new Tier("Gilded", 42, 87, ObjectID.POH_COS_ROOM_MAGIC_WARDROBE_MAHOGANY_GILDED, ObjectID.POH_COS_ROOM_MAGIC_WARDROBE_OPEN_MAHOGANY_GILDED),
