package com.ultimatebank.feature.storagesavings;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

public class IgnoreListTest
{
	private static final Map<String, Set<Integer>> NAMES = Map.of(
		IgnoreList.normalize("Mystic robe top"), Set.of(4091),
		IgnoreList.normalize("Mystic robe top (dark)"), Set.of(4101),
		IgnoreList.normalize("Watering can(7)"), Set.of(5333),
		// Two items sharing a name, e.g. a quest and non-quest variant
		IgnoreList.normalize("Bullseye lantern"), Set.of(4550, 9065)
	);

	@Test
	public void emptyListIgnoresNothing()
	{
		assertEquals(Set.of(), IgnoreList.resolve("", NAMES));
		assertEquals(Set.of(), IgnoreList.resolve(null, NAMES));
	}

	@Test
	public void namesMatchIgnoringCaseAndSpaces()
	{
		assertEquals(Set.of(4091), IgnoreList.resolve("mySTic   robetop", NAMES));
	}

	@Test
	public void sharedNameIgnoresEveryItem()
	{
		assertEquals(Set.of(4550, 9065), IgnoreList.resolve("Bullseye lantern", NAMES));
	}

	@Test
	public void numbersAreItemIds()
	{
		assertEquals(Set.of(1234, 4091), IgnoreList.resolve("1234, Mystic robe top", NAMES));
	}

	@Test
	public void hugeNumberIsSkipped()
	{
		assertEquals(Set.of(), IgnoreList.resolve("99999999999999", NAMES));
	}

	@Test
	public void wildcardsMatchAndTreatBracketsLiterally()
	{
		assertEquals(Set.of(4091, 4101), IgnoreList.resolve("*mystic robe top*", NAMES));
		assertEquals(Set.of(5333), IgnoreList.resolve("watering can(*)", NAMES));
	}

	@Test
	public void unknownNameIsSkipped()
	{
		assertEquals(Set.of(), IgnoreList.resolve("Not an item", NAMES));
	}

	@Test
	public void addAndRemoveExactEntries()
	{
		String list = IgnoreList.add("*cape*", "Mystic robe top");
		assertTrue(IgnoreList.containsExact(list, "Mystic robe top", 4091));

		list = IgnoreList.remove(list, "Mystic robe top", 4091);
		assertFalse(IgnoreList.containsExact(list, "Mystic robe top", 4091));
		assertEquals("Wildcards are left alone", "*cape*", list);
	}

	@Test
	public void removeMatchesById()
	{
		assertEquals("", IgnoreList.remove("4091", "Mystic robe top", 4091));
	}
}

package com.ultimatebank.feature.storagesavings;

import static org.junit.Assert.assertEquals;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import org.junit.Test;

public class StorableLayoutTest
{
	@Test
	public void eachGroupGetsATitleRowThenItsItems()
	{
		StorableLayout.Result result = StorableLayout.build(List.of(
			new StorableLayout.Group("POH toy box", List.of(1, 2, 3, 4, 5, 6, 7, 8, 9)),
			new StorableLayout.Group("Tackle box", List.of(10))));

		// Row 0 title, rows 1-2 toy box items, row 3 title, row 4 tackle box
		assertEquals(Map.of(0, "POH toy box", 3, "Tackle box"), result.getTitleRows());
		int[] p = result.getPositions();
		assertEquals(-1, p[0]);
		assertEquals(1, p[8]);
		assertEquals(9, p[16]);
		assertEquals(-1, p[17]);
		assertEquals(10, p[32]);
		assertEquals(33, p.length);
	}

	@Test
	public void emptyGroupsAreSkipped()
	{
		StorableLayout.Result result = StorableLayout.build(List.of(
			new StorableLayout.Group("Empty", List.of()),
			new StorableLayout.Group("Spice rack", List.of(5))));
		assertEquals(Map.of(0, "Spice rack"), result.getTitleRows());
		assertEquals(5, result.getPositions()[8]);
	}

	@Test
	public void itemInTwoContainersAppearsInBoth()
	{
		StorableLayout.Result result = StorableLayout.build(List.of(
			new StorableLayout.Group("A", List.of(7)),
			new StorableLayout.Group("B", List.of(7))));
		assertEquals(7, result.getPositions()[8]);
		assertEquals(7, result.getPositions()[24]);
	}

	@Test
	public void focusedGroupKeepsItsTitleWhenEmptied()
	{
		StorableLayout.Result result = StorableLayout.build(List.of(new StorableLayout.Group("Toy box", List.of())), true);
		assertEquals(Map.of(0, "Toy box"), result.getTitleRows());
		assertEquals(8, result.getPositions().length);
	}

	@Test
	public void keepOrderHoldsPreviousPlacesAndAppendsNewGroups()
	{
		List<StorableLayout.Group> ranking = List.of(
			new StorableLayout.Group("Tackle box", List.of(3)),
			new StorableLayout.Group("New", List.of(4)),
			new StorableLayout.Group("Toy box", List.of(1)),
			new StorableLayout.Group("Also new", List.of(5)));

		List<StorableLayout.Group> kept = StorableLayout.keepOrder(List.of("Toy box", "Gone", "Tackle box"), ranking);
		assertEquals(List.of("Toy box", "Tackle box", "New", "Also new"),
			kept.stream().map(StorableLayout.Group::getTitle).collect(Collectors.toList()));
	}
}

