package com.ultimatebank.feature.storagesavings.tiers;

import static org.junit.Assert.assertEquals;
import java.util.List;
import java.util.Set;
import org.junit.Test;

public class TierPlannerTest
{
	private static TierPlanner.StorageSet set(String name, Integer... ids)
	{
		return new TierPlanner.StorageSet(name, Set.of(ids), false, -1);
	}

	// Mime 5 pieces banked, Zombie 3, Frog 1
	private static final List<TierPlanner.StorageSet> COSTUMES = List.of(
		set("Mime", 1, 2, 3, 4, 5), set("Zombie", 10, 11, 12), set("Frog", 20), set("Camo", 30, 31));
	private static final Set<Integer> BANKED = Set.of(1, 2, 3, 4, 5, 10, 11, 12, 20);

	@Test
	public void limitedTierPicksTheSetsFreeingMostSlots()
	{
		// Oak fancy dress box: 2 costumes -> Mime (5) and Zombie (3), not Frog (1)
		assertEquals(Set.of(1, 2, 3, 4, 5, 10, 11, 12),
			TierPlanner.fits(PohStorage.Limit.SETS, 2, COSTUMES, BANKED, Set.of()));
	}

	@Test
	public void storedSetsKeepTheirSlotAndCountAgainstCapacity()
	{
		// Frog already stored (uses 1 of 2 slots): its banked piece fits, plus the biggest other set
		assertEquals(Set.of(20, 1, 2, 3, 4, 5),
			TierPlanner.fits(PohStorage.Limit.SETS, 2, COSTUMES, BANKED, Set.of(20)));
	}

	@Test
	public void fullStorageOnlyTakesStoredSets()
	{
		assertEquals(Set.of(), TierPlanner.fits(PohStorage.Limit.SETS, 1, COSTUMES, BANKED, Set.of(30)));
	}

	@Test
	public void unlimitedTakesEverything()
	{
		assertEquals(BANKED, TierPlanner.fits(PohStorage.Limit.SETS, PohStorage.Tier.UNLIMITED, COSTUMES, BANKED, Set.of()));
	}

	@Test
	public void capeRackOnlyLimitsCapesOfAccomplishment()
	{
		List<TierPlanner.StorageSet> capes = List.of(
			new TierPlanner.StorageSet("Attack cape", Set.of(1, 2), true, -1),
			new TierPlanner.StorageSet("Agility cape", Set.of(3), true, -1),
			new TierPlanner.StorageSet("Fire cape", Set.of(9), false, -1));
		// Oak rack: no skillcapes, but the fire cape fits
		assertEquals(Set.of(9), TierPlanner.fits(PohStorage.Limit.ACCOMPLISHMENT_CAPES, 0, capes, Set.of(1, 2, 3, 9), Set.of()));
		// Teak rack: 1 skillcape (the one freeing most slots)
		assertEquals(Set.of(1, 2, 9), TierPlanner.fits(PohStorage.Limit.ACCOMPLISHMENT_CAPES, 1, capes, Set.of(1, 2, 3, 9), Set.of()));
	}

	@Test
	public void treasureChestTakesRewardsUpToItsClueTier()
	{
		List<TierPlanner.StorageSet> rewards = List.of(
			new TierPlanner.StorageSet("Easy", Set.of(1), false, PohStorage.ClueTier.EASY.ordinal()),
			new TierPlanner.StorageSet("Medium", Set.of(2), false, PohStorage.ClueTier.MEDIUM.ordinal()),
			new TierPlanner.StorageSet("Elite", Set.of(3), false, PohStorage.ClueTier.ELITE.ordinal()));
		// Oak chest: up to easy
		assertEquals(Set.of(1), TierPlanner.fits(PohStorage.Limit.CLUE_TIER, PohStorage.ClueTier.EASY.ordinal(),
			rewards, Set.of(1, 2, 3), Set.of()));
		// Unknown items (in no set) aren't blocked
		assertEquals(Set.of(1, 2, 99), TierPlanner.fits(PohStorage.Limit.CLUE_TIER, PohStorage.ClueTier.MEDIUM.ordinal(),
			rewards, Set.of(1, 2, 3, 99), Set.of()));
	}
}

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RadialGradientPaint;
import java.awt.RenderingHints;
import java.awt.geom.AffineTransform;
import java.awt.geom.Ellipse2D;
import java.awt.geom.GeneralPath;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.Random;
import javax.imageio.ImageIO;

/**
 * Draws the Plugin Hub icon (48x72): an open chest whose inside is a starry void, with a vortex widening upwards
 * and items bigger than the chest floating out of it ("bigger on the inside").
 *
 * usage (JDK 11+): java tools/make_icon/MakeIcon.java icon.png [preview.png]
 */
public class MakeIcon
{
	private static final int W = 48;
	private static final int H = 72;
	/** Drawn at this scale, then smoothly downsampled */
	private static final int S = 8;

	public static void main(String[] args) throws Exception
	{
		BufferedImage big = new BufferedImage(W * S, H * S, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = big.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
		g.scale(S, S);

		drawLid(g);
		drawVortex(g);
		drawItems(g);
		drawChest(g);
		g.dispose();

		BufferedImage icon = downsample(big, W, H);
		ImageIO.write(icon, "png", new File(args[0]));
		if (args.length > 1)
		{
			ImageIO.write(upscale(icon, 6), "png", new File(args[1]));
		}
	}

	/** A purple funnel rising from the chest mouth, much wider than the chest at the top */
	private static void drawVortex(Graphics2D g)
	{
		GeneralPath funnel = new GeneralPath();
		funnel.moveTo(18, 48);
		funnel.curveTo(15, 38, 2, 26, 1, 6);
		funnel.curveTo(14, 1, 34, 1, 47, 6);
		funnel.curveTo(46, 26, 33, 38, 30, 48);
		funnel.closePath();
		g.setPaint(new GradientPaint(0, 47, new Color(120, 60, 200, 230), 0, 2, new Color(70, 40, 160, 40)));
		g.fill(funnel);

		// Swirl lines
		g.setStroke(new BasicStroke(0.7f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		for (int i = 0; i < 4; i++)
		{
			float y = 44 - i * 10;
			float half = 7 + i * 6.5f;
			g.setColor(new Color(200, 170, 255, 170 - i * 30));
			g.draw(new java.awt.geom.Arc2D.Float(24 - half, y - 2.5f, half * 2, 5, 200, 250, java.awt.geom.Arc2D.OPEN));
		}

		// Stars
		Random random = new Random(7);
		for (int i = 0; i < 18; i++)
		{
			float y = 6 + random.nextFloat() * 38;
			float spread = 10 + (47 - y) * 0.45f;
			float x = 24 + (random.nextFloat() * 2 - 1) * spread * 0.85f;
			float r = random.nextFloat() < 0.25f ? 0.9f : 0.5f;
			g.setColor(new Color(255, 245, 200, 220));
			g.fill(new Ellipse2D.Float(x - r, y - r, r * 2, r * 2));
		}
	}

	/** Items larger than the chest itself, floating up out of the vortex */
	private static void drawItems(Graphics2D g)
	{
		// Sword, tilted
		AffineTransform saved = g.getTransform();
		g.translate(30, 24);
		g.rotate(Math.toRadians(28));
		g.setColor(new Color(215, 225, 235));
		g.fill(new Polygon(new int[]{-2, 2, 2, 0, -2}, new int[]{-16, -16, 8, 11, 8}, 5));
		g.setColor(new Color(150, 160, 175));
		g.fill(new java.awt.Rectangle(0, -16, 1, 24));
		g.setColor(new Color(212, 175, 55));
		g.fill(new RoundRectangle2D.Float(-6, -18, 12, 2.5f, 1, 1));
		g.setColor(new Color(110, 70, 40));
		g.fill(new java.awt.Rectangle(-1, -24, 2, 6));
		g.setColor(new Color(212, 175, 55));
		g.fill(new Ellipse2D.Float(-1.6f, -26, 3.2f, 3.2f));
		g.setTransform(saved);

		// Cape, flowing
		GeneralPath cape = new GeneralPath();
		cape.moveTo(9, 13);
		cape.lineTo(19, 13);
		cape.curveTo(21, 21, 21, 29, 22, 36);
		cape.curveTo(17, 34, 11, 37, 6, 34);
		cape.curveTo(8, 27, 8, 20, 9, 13);
		cape.closePath();
		g.setPaint(new GradientPaint(0, 13, new Color(200, 40, 40), 0, 36, new Color(120, 15, 25)));
		g.fill(cape);
		g.setColor(new Color(240, 200, 80));
		g.fill(new RoundRectangle2D.Float(8.5f, 12, 11, 2.5f, 1, 1));

		// Potion
		g.setColor(new Color(200, 230, 255, 200));
